// Owner-editable lists; album ids must match content/gallery.json, playlist ids come from YouTube Studio.
const cfg = {
  site: 'https://unifight-haifa.github.io/unifight',
  review_chat_id: '',
  // Originals stay in this private repo; the public site pulls a resized copy via repository_dispatch.
  staging_repo: 'Unifight-haifa/media-inbox',
  albums: [
    { id: 'training', name: 'Тренировки' }, { id: 'competitions', name: 'Соревнования' },
    { id: 'camps', name: 'Сборы' }, { id: 'club', name: 'Клуб' }, { id: 'history', name: 'История' },
  ],
  playlists: [
    { name: 'Соревнования', id: 'REPLACE_PLAYLIST_ID' }, { name: 'Сборы', id: 'REPLACE_PLAYLIST_ID' },
    { name: 'Промо-съёмки клуба', id: 'REPLACE_PLAYLIST_ID' },
  ],
  yt_title_lang: 'he',
};
return $input.all().map(it => ({ json: { ...it.json, cfg } }));

const m = $('Config').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.active === true);
const approvers = rows.filter(r => ['approver', 'admin'].includes(r.role) && r.telegram_id)
  .map(r => ({ coach_id: r.coach_id, name: r.name || r.coach_id, telegram_id: String(r.telegram_id) }));
if (!approvers.length) throw new Error('media-review: no active approver/admin with telegram_id in publishers');
const author = rows.find(r => r.coach_id === m.author_id) || {};
const kind = m.type === 'video' ? 'Видео' : 'Фото';
const card = [
  `${kind} от ${author.name || m.author_id}`,
  ...(m.caption ? [`Подпись: ${m.caption}`] : []),
  `Файл: ${m.file_name}`, `Drive: ${m.drive_link}`, '',
  m.type === 'video' ? 'Загрузить на YouTube клуба или оставить только в папке?' : 'Поставить в галерею сайта или оставить только в папке?',
].join('\n');
return [{ json: {
  ...m, approvers, approver_ids: approvers.map(a => a.telegram_id).join(','),
  review_chat: m.cfg.review_chat_id || approvers[0].telegram_id,
  author_name: author.name || m.author_id, card,
} }];

// A timeout also resumes the node; it has no responder, so it must not count as a rejection.
const m = $('Approvers').first().json;
const d = $input.first().json.data ?? $input.first().json;
const who = d.user ?? d.from ?? d.responder ?? {};
const tgId = String(who.id ?? d.userId ?? '');
const decider = m.approvers.find(a => a.telegram_id === tgId) || { coach_id: tgId ? `tg:${tgId}` : '', name: who.first_name || '', telegram_id: tgId };
let decision = 'timeout';
if (d.approved === true) decision = m.type === 'video' ? 'youtube' : 'site';
else if (d.approved === false && tgId) decision = 'reject';
return [{ json: { decision, decider, decider_chat: decider.telegram_id || m.review_chat } }];

const m = $('Approvers').first().json;
const kind = m.type === 'video' ? 'Видео' : 'Фото';
return m.author_tg ? [{ json: { chat_id: m.author_tg, text: `${kind} ${m.file_name} осталось в папке клуба, публиковать его не будем.` } }] : [];

const m = $('Approvers').first().json;
const d = $input.first().json.data ?? $input.first().json;
const album = m.cfg.albums.find(a => a.name === d['Альбом']);
const alt = String(d['Что на фото'] ?? '').trim();
// Form timed out: leave the item as status=new in the media table.
if (!album || !alt) return [];
return [{ json: { album: album.id, album_name: album.name,
  context: 'short alt text describing a photo in the club website gallery; never name children', fields: { alt }, limits: { alt: 150 } } }];

const m = $('Approvers').first().json;
const s = $('Site Input').last().json;
const t = $('Translate Alt').last().json;
const dec = $('Decision').first().json.decider;
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const file = String(m.file_name).toLowerCase().replace(/[^a-z0-9._-]+/g, '-');
const stem = file.replace(/\.[^.]+$/, '');
if (!/\.(jpe?g|png|heic)$/.test(file)) throw new Error(`Gallery intake takes JPEG, PNG or HEIC only: ${file}`);
const dir = `incoming/gallery/${s.album}`;
const sidecar = { album: s.album, alt: { he: t.tr.he.alt, ru: t.tr.ru.alt, en: t.tr.en.alt }, author: m.author_id, approved_by: dec.coach_id };
return [{ json: {
  repo: m.cfg.staging_repo, dispatch: { event_type: 'gallery-intake', client_payload: { path: `${dir}/${file}` } },
  files: [{ path: `${dir}/${file}`, b64: buf.toString('base64') }, { path: `${dir}/${file}.json`, content: JSON.stringify(sidecar, null, 1) + '\n' }],
  message: `Gallery: ${s.album}/${file}\n\nFrom ${m.author_id} via telegram, approved by ${dec.coach_id}`,
  live_url: `${m.cfg.site}/gallery.json`, live_match: `"${stem}"`, site_path: `${dir}/${file}`,
} }];

const m = $('Approvers').first().json;
const c = $input.first().json;
const dec = $('Decision').first().json;
const text = c.live
  ? `Фото в галерее сайта: ${m.cfg.site}/ru/gallery/`
  : `Фото отправлено на сайт (коммит ${String(c.sha).slice(0, 7)}), но в галерее пока не появилось. Проверьте позже: ${m.cfg.site}/ru/gallery/`;
const chats = [...new Set([m.author_tg, dec.decider_chat].filter(Boolean))];
return chats.map(chat_id => ({ json: { chat_id, text, notify_admin: !c.live } }));

const m = $('Approvers').first().json;
const d = $input.first().json.data ?? $input.first().json;
const title = String(d['Название'] ?? '').trim();
// Form timed out: leave the item as status=new in the media table.
if (!title) return [];
const pl = m.cfg.playlists.find(p => p.name === d['Плейлист']);
return [{ json: {
  privacy: /public|Публично/.test(String(d['Доступ'])) ? 'public' : 'unlisted',
  minors: !/Нет/.test(String(d['В кадре есть дети до 18?'])),
  music: String(d['Музыка'] ?? '').trim(), playlist_id: pl ? pl.id : '', playlist_name: pl ? pl.name : '',
  context: 'YouTube video title and description for a judo club channel; never name children',
  fields: { title, description: String(d['Описание'] ?? '').trim() }, limits: { title: 100, description: 1500 },
} }];

const m = $('Approvers').first().json;
const y = $('YT Input').last().json;
const t = $('Translate YT').last().json.tr;
const consent = $('Consent').isExecuted && ($('Consent').last().json.data ?? {}).approved === true;
const privacy = y.privacy === 'public' && (!y.minors || consent) ? 'public' : 'unlisted';
const block = l => [t[l].title, t[l].description].filter(Boolean).join('\n');
const description = [block('he'), block('ru'), block('en'), y.music ? `Music: ${y.music}` : '', m.cfg.site]
  .filter(Boolean).join('\n\n').slice(0, 4900);
return [{ json: {
  title: t[m.cfg.yt_title_lang].title.slice(0, 100), description, privacy,
  downgraded: privacy !== y.privacy, playlist_id: y.playlist_id,
  localizations: Object.fromEntries(['he', 'ru', 'en'].map(l => [l, { title: t[l].title.slice(0, 100), description: block(l) || t[l].title }])),
} }];

const m = $('Approvers').first().json;
const meta = $('YT Meta').first().json;
const up = $('YouTube Upload').first().json;
const dec = $('Decision').first().json;
const id = up.uploadId || up.id || '';
let pl = '';
if (meta.playlist_id) {
  const added = $('Add To Playlist').isExecuted && !!$('Add To Playlist').first().json.id;
  pl = added ? '\nДобавлено в плейлист.' : '\nВ плейлист не добавлено (проверьте id плейлиста в Config).';
}
const text = `Видео на YouTube: https://youtu.be/${id}\nДоступ: ${meta.privacy === 'public' ? 'публичное' : 'по ссылке'}`
  + (meta.downgraded ? ' (публичным не сделано: нет подтверждения согласия родителей)' : '') + pl;
const chats = [...new Set([m.author_tg, dec.decider_chat].filter(Boolean))];
return chats.map(chat_id => ({ json: { chat_id, text, youtube_id: id } }));
